97.sql:
SELECT DISTINCT d.client_id
FROM disp d
WHERE d.type = 'OWNER';

267.sql:
SELECT bond_type
FROM bond
WHERE molecule_id BETWEEN 'TR000' AND 'TR050';

291.sql:
SELECT COUNT(*) AS answer
FROM molecule
WHERE label = '+';

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE borderColor = 'borderless' AND edhrecRank > 12000;

591.sql:
SELECT COUNT(DISTINCT b.UserId) AS answer
FROM badges AS b
WHERE b.Name = 'Supporter' AND strftime('%Y', b.Date) = '2011';

617.sql:
SELECT Text
FROM comments
WHERE CreationDate = '2010-07-19 19:37:33.0';

631.sql:
WITH final_count AS (
    SELECT COUNT(*) AS answer
    FROM posts
    WHERE OwnerUserId = (
        SELECT Id
        FROM users
        WHERE DisplayName = 'Daniel Vassallo'
    )
)
SELECT answer FROM final_count;

882.sql:
SELECT MIN(year) AS first_year
FROM races
WHERE name = 'Singapore Grand Prix';

996.sql:
SELECT (COUNT(*) / 11.0) AS annual_average
FROM races
WHERE date BETWEEN '2000-01-01' AND '2010-12-31';

1035.sql:
SELECT DISTINCT `team_fifa_api_id`
FROM Team_Attributes
WHERE `buildUpPlaySpeed` > 50 AND `buildUpPlaySpeed` < 60;

1393.sql:
SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';
